text:
{
  "introducao_ludica": "Olá, exploradores da matemática! Hoje, nossa sala de aula vai se transformar em uma pizzaria! Imagine que pedimos uma pizza deliciosa para dividir entre nós. Mas como garantimos que todos recebam um pedaço justo? As frações são a receita secreta para essa divisão! Vamos descobrir juntos como fatiar o conhecimento e saborear cada pedaço do aprendizado.",
  "objetivo_bncc": {
    "descricao": "Esta aula desenvolve a habilidade de identificar e representar frações como partes de um inteiro (figuras ou objetos), reconhecendo que o todo foi dividido em partes iguais. O foco está em compreender os significados do numerador (quantas partes foram consideradas) e do denominador (em quantas partes o todo foi dividido), em alinhamento com a habilidade EF05MA03, que trata da representação de frações e sua associação com a ideia de parte-todo.",
    "codigos_relacionados": [
      "EF05MA03"
    ]
  },
  "passo_a_passo": [
    {
      "etapa": 1,
      "descricao": "Roda de conversa 'A Pizzaria Matemática': O professor desenha uma pizza no quadro e pergunta aos alunos como dividi-la igualmente para 2, 4 e 8 amigos. A cada divisão, introduz os conceitos de fração, numerador (pedaços que 'comemos') e denominador (total de pedaços).",
      "materiais": [
        "Quadro",
        "Pincel para quadro"
      ],
      "tempo_min": 10
    },
    {
      "etapa": 2,
      "descricao": "Mão na Massa - 'Montando Frações': Em pequenos grupos, os alunos recebem círculos ou retângulos de papel colorido (representando pizzas ou barras de chocolate). Eles devem seguir os comandos do professor para dobrar e cortar, representando fisicamente frações como 1/2, 1/4, 3/4 e 1/8. Cada grupo monta suas frações e as exibe.",
      "materiais": [
        "Círculos ou retângulos de papel colorido",
        "Tesoura sem ponta",
        "Cola"
      ],
      "tempo_min": 20
    },
    {
      "etapa": 3,
      "descricao": "Desafio no Quadro: O professor propõe desafios rápidos no quadro, utilizando os materiais concretos dos alunos como apoio. Exemplos: 'Se eu comi 2/8 da pizza e você comeu 3/8, quem comeu mais?'. 'Representem a fração 5/6 usando suas barras de chocolate.' Os alunos respondem mostrando suas representações ou falando.",
      "materiais": [
        "Quadro",
        "Pincel para quadro",
        "Materiais concretos produzidos na etapa 2"
      ],
      "tempo_min": 15
    },
    {
      "etapa": 4,
      "descricao": "Fechamento e Sistematização: O professor faz uma rápida revisão, perguntando o que é uma fração, o que o número de cima indica e o que o número de baixo indica. Pede para os alunos darem um exemplo de fração que aprenderam no dia.",
      "materiais": [],
      "tempo_min": 5
    }
  ],
  "rubrica_avaliacao": [
    {
      "criterio": "Identificação de Frações",
      "iniciante": "Confunde numerador e denominador e tem dificuldade em nomear uma fração a partir de uma representação visual, mesmo com ajuda.",
      "intermediario": "Identifica corretamente frações comuns (1/2, 1/4) em representações visuais, mas pode precisar de apoio para frações menos usuais.",
      "avancado": "Identifica e nomeia com segurança diversas frações a partir de representações visuais, explicando o papel do numerador e do denominador."
    },
    {
      "criterio": "Representação de Frações com Material Concreto",
      "iniciante": "Apresenta grande dificuldade em dividir o todo em partes iguais para representar a fração solicitada.",
      "intermediario": "Consegue representar frações simples (denominadores 2, 4), mas pode não garantir que as partes sejam perfeitamente iguais.",
      "avancado": "Representa com precisão e autonomia diferentes frações solicitadas, garantindo a divisão do todo em partes iguais."
    },
    {
      "criterio": "Comparação Simples de Frações",
      "iniciante": "Não consegue comparar duas frações com o mesmo denominador, mesmo utilizando apoio visual.",
      "intermediario": "Compara frações com o mesmo denominador utilizando o apoio do material concreto, mas tem dificuldade em fazê-lo apenas com a representação numérica.",
      "avancado": "Compara frações com o mesmo denominador de forma abstrata e explica seu raciocínio (ex: '3/8 é maior que 2/8 porque 3 pedaços é mais que 2 pedaços')."
    }
  ]
}

